    scales = [1, 4, 8]
    grounds = [("light", LIGHT), ("dark", DARK), ("busy", "busy")]
    pad, cell_w = 8, 32 * 8
    row_h = cell_w + pad
    sheet_w = pad + len(grounds) * len(scales) * (cell_w + pad)
    sheet_h = pad + len(variants) * (row_h + pad)
