def commit(folder, candidate, expected, root=None):
    folder = Path(folder).resolve()
    with lock(folder):
        current = load(folder)
        validate(
            current
        )  # Drift in files can be repaired by a correctly grounded candidate.
        if digest(current) != expected:
            raise PixlError(
                "stale_write",
